using DomainModel.Models; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DomainModel.Configurations; public class UserMembershipConfiguration:IEntityTypeConfiguration<UserMembership>{ public void Configure(EntityTypeBuilder<UserMembership>b){ b.HasKey(x=>x.UserMembershipID); b.Property(x=>x.PaidAmount).HasPrecision(18,0); b.HasIndex(x=>new{x.UserID,x.IsActive}); b.HasOne(x=>x.User).WithMany(x=>x.UserMemberships).HasForeignKey(x=>x.UserID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x=>x.MembershipPlan).WithMany(x=>x.UserMemberships).HasForeignKey(x=>x.MembershipPlanID).OnDelete(DeleteBehavior.Restrict); }}